1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_RATE = 0.1;
3	const DEDUCTIBLE = 100;
4	const CAP_MULTIPLIER = 2;
5	
6	interface CatalogEntry {
7	  basePremium: number;
8	  insuranceValue: number;
9	}
10	
11	const CATALOG: Record<string, CatalogEntry> = {
12	  sword: { basePremium: 100, insuranceValue: 1000 },
13	  amulet: { basePremium: 60, insuranceValue: 600 },
14	  staff: { basePremium: 80, insuranceValue: 800 },
15	  potion: { basePremium: 40, insuranceValue: 400 },
16	  rune: { basePremium: 25, insuranceValue: 250 },
17	  moonstone: { basePremium: 25, insuranceValue: 250 },
18	};
19	
20	const basePremiumOf = (type: string): number => CATALOG[type]?.basePremium ?? 0;
21	const insuranceValueOf = (type: string): number => CATALOG[type]?.insuranceValue ?? 0;
22	
23	interface Item {
24	  type: string;
25	  material?: string;
26	  enchantment?: number;
27	  cursed?: boolean;
28	}
29	
30	const HIGH_ENCHANTMENT_THRESHOLD = 5;
31	
32	const isCursed = (item: Item): boolean => item.cursed === true;
33	const isHighlyEnchanted = (item: Item): boolean =>
34	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
35	
36	const SURCHARGE_RATES: ReadonlyArray<{ applies: (item: Item) => boolean; rate: number }> = [
37	  { applies: isCursed, rate: 0.5 },
38	  { applies: isHighlyEnchanted, rate: 0.3 },
39	];
40	
41	const itemSurcharge = (item: Item): number => {
42	  const base = basePremiumOf(item.type);
43	  const totalRate = SURCHARGE_RATES
44	    .filter(({ applies }) => applies(item))
45	    .reduce((sum, { rate }) => sum + rate, 0);
46	  return base * totalRate;
47	};
48	
49	const itemsSurcharge = (items: Item[]): number =>
50	  items.reduce((sum, item) => sum + itemSurcharge(item), 0);
51	
52	interface QuoteStep {
53	  op: "quote";
54	  items: Item[];
55	}
56	
57	interface Damage {
58	  itemType: string;
59	  amount: number;
60	}
61	
62	interface ClaimStep {
63	  op: "claim";
64	  policy: number;
65	  incident: {
66	    cause: string;
67	    damages: Damage[];
68	  };
69	}
70	
71	type Step = QuoteStep | ClaimStep;
72	
73	interface Customer {
74	  yearsWithMHPCO: number;
75	}
76	
77	interface Scenario {
78	  customer: Customer;
79	  steps: Step[];
80	}
81	
82	interface QuoteResult {
83	  premium: number;
84	}
85	
86	interface ClaimResult {
87	  payout: number;
88	  remainingCap: number;
89	}
90	
91	type StepResult = QuoteResult | ClaimResult;
92	
93	interface ScenarioResult {
94	  results: StepResult[];
95	}
96	
97	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
98	const COMPONENT_BLOCK_SIZE = 3;
99	const COMPONENT_BLOCK_BASE = 60;
100	
101	const roundUpInMHPCOsFavor = (amount: number): number => Math.ceil(amount);
102	const roundDownInMHPCOsFavor = (amount: number): number => Math.floor(amount);
103	
104	const groupCountsByType = (items: Item[]): Map<string, number> => {
105	  const counts = new Map<string, number>();
106	  for (const item of items) {
107	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
108	  }
109	  return counts;
110	};
111	
112	const typeBasePremium = (type: string, count: number): number => {
113	  if (COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE) {
114	    return COMPONENT_BLOCK_BASE;
115	  }
116	  return basePremiumOf(type) * count;
117	};
118	
119	const itemsBasePremium = (items: Item[]): number =>
120	  [...groupCountsByType(items)].reduce(
121	    (total, [type, count]) => total + typeBasePremium(type, count),
122	    0,
123	  );
124	
125	const firstInsuranceSurcharge = (base: number): number => base * FIRST_INSURANCE_RATE;
126	
127	const LOYALTY_YEARS_THRESHOLD = 2;
128	const LOYALTY_DISCOUNT_RATE = 0.2;
129	
130	const isLoyalCustomer = (customer: Customer): boolean =>
131	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
132	
133	const loyaltyDiscount = (customer: Customer, base: number): number =>
134	  isLoyalCustomer(customer) ? base * LOYALTY_DISCOUNT_RATE : 0;
135	
136	const quotePremium = ({ items }: QuoteStep, customer: Customer): number => {
137	  const base = itemsBasePremium(items);
138	  const premiumBeforeFee =
139	    base + itemsSurcharge(items) + firstInsuranceSurcharge(base) - loyaltyDiscount(customer, base);
140	  return roundUpInMHPCOsFavor(premiumBeforeFee + PROCESSING_FEE);
141	};
142	
143	interface Policy {
144	  items: Item[];
145	  remainingCap: number;
146	}
147	
148	const itemInsuranceValue = (item: Item): number => insuranceValueOf(item.type);
149	
150	const createPolicy = (step: QuoteStep): Policy => {
151	  const insuranceSum = step.items.reduce((sum, item) => sum + itemInsuranceValue(item), 0);
152	  return { items: step.items, remainingCap: insuranceSum * CAP_MULTIPLIER };
153	};
154	
155	const reimbursementFor = (item: Item, damageAmount: number): number =>
156	  isHighlyEnchanted(item) ? damageAmount * 0.5 : damageAmount;
157	
158	const damagePayout = (damage: Damage, item: Item): number =>
159	  Math.max(0, reimbursementFor(item, damage.amount) - DEDUCTIBLE);
160	
161	const findItem = (policy: Policy, itemType: string): Item =>
162	  policy.items.find((i) => i.type === itemType)!;
163	
164	const processClaim = (step: ClaimStep, policies: Map<number, Policy>): ClaimResult => {
165	  const policy = policies.get(step.policy)!;
166	  const rawPayout = step.incident.damages.reduce(
167	    (sum, d) => sum + damagePayout(d, findItem(policy, d.itemType)),
168	    0,
169	  );
170	  const payout = roundDownInMHPCOsFavor(Math.min(rawPayout, policy.remainingCap));
171	  policy.remainingCap -= payout;
172	  return { payout, remainingCap: policy.remainingCap };
173	};
174	
175	export const runScenario = (scenario: Scenario): ScenarioResult => {
176	  const policies = new Map<number, Policy>();
177	  const results: StepResult[] = scenario.steps.map((step, index) => {
178	    if (step.op === "quote") {
179	      policies.set(index, createPolicy(step));
180	      return { premium: quotePremium(step, scenario.customer) };
181	    }
182	    return processClaim(step, policies);
183	  });
184	  return { results };
185	};
